class QByteArray {
public:
    QByteArray() = default;
    QByteArray(const char* s) : data_(s) {}
    QByteArray(std::string s) : data_(std::move(s)) {}
    bool isEmpty() const { return data_.empty(); }
    const char* constData() const { return data_.c_str(); }
    const char* data() const { return data_.c_str(); }
    size_t size() const { return data_.size(); }
    void append(char c) { data_.push_back(c); }
    void append(const char* s, size_t n) { data_.append(s, n); }
    std::string& str() { return data_; }
    const std::string& str() const { return data_; }
private:
    std::string data_;
};

class QByteArrayView {
public:
    QByteArrayView() : ptr_(nullptr), len_(0) {}
    QByteArrayView(const QByteArray& ba) : ptr_(ba.data()), len_(ba.size()) {}
    QByteArrayView(const char* s) : ptr_(s), len_(strlen(s)) {}
    QByteArrayView(const char* p, size_t n) : ptr_(p), len_(n) {}
    const char* data() const { return ptr_; }
    size_t size() const { return len_; }
private:
    const char* ptr_;
    size_t len_;
};

