// Harness for KCodecs::base64Encode(QByteArrayView in, bool useCRLF)
// Inputs:
//   - in_buf: persistent QByteArray* managed by the fuzzer runtime; we must not free it.
// Outputs:
//   - in_buf: returned unchanged to keep it alive in the pool
//   - encoded: newly allocated QByteArray* holding the Base64 result

// Randomize the CRLF flag
bool useCRLF = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

// Build a QByteArrayView over valid readable memory owned by in_buf.
// We exercise two construction paths to increase coverage:
//   1) from the full QByteArray (safe, lifetime guaranteed during call)
//   2) from (ptr, len) subrange bounded within in_buf->data() [0..size]
QByteArrayView view;{
    unsigned int ctor_choice = (*FUZZ_PARAM(unsigned int)) & 1u;
    if (ctor_choice == 0) {
        // Full view over the entire QByteArray
        view = QByteArrayView(*in_buf);
    } else {
        // Subrange view: length constrained to be within the buffer
        size_t maxLen = in_buf->size();
        size_t subLen = (maxLen == 0) ? 0 : ((size_t)(*FUZZ_PARAM(unsigned int)) % (maxLen + 1));
        view = QByteArrayView(in_buf->data(), subLen);
    }
}

// Call the target function
QByteArray result = KCodecs::base64Encode(view, useCRLF);

// Persist the return value by allocating a new QByteArray object for the pool
QByteArray *encoded = new QByteArray(result);

// Property-based sanity check: empty input must yield empty output
FUZZ_ASSERT((view.size() == 0) == (encoded->size() == 0), "Base64 encoding of empty input should be empty");

// Validation summary:
// - view always references valid readable memory owned by in_buf for the call duration.
// - useCRLF randomized via FUZZ_PARAM; no other constraints assumed.
// - encoded is non-null and returned; in_buf is returned to avoid dropping ownership.

// Constructor stub for QByteArray*
// Goal: produce a valid, bounded-size QByteArray instance using multiple construction paths
// Outputs:
//   - ba: newly allocated QByteArray* returned to the object pool (non-null)

// Allocate the object managed by the fuzzer runtime after return
QByteArray *ba = new QByteArray();

// Generate a fuzz string as the data source; we will cap size to keep allocations fast
std::string seed = FUZZ_PARAM_STR();
const size_t kMaxSize = 2048; // keep allocations bounded

// Constrain the initial content length to <= kMaxSize
size_t initLen = seed.size();
if (initLen > kMaxSize) initLen = kMaxSize;

// Choose a construction mode to exercise different API paths
unsigned int mode = (*FUZZ_PARAM(unsigned int)) % 3u;
if (mode == 0u) {
    // Directly assign via std::string-based path
    ba->str().assign(seed.data(), initLen);
} else if (mode == 1u) {
    // Simulate construction from std::string then assign
    std::string tmp = seed.substr(0, initLen);
    QByteArray tmpBA(std::move(tmp));
    // Copy-assign into the allocated object to avoid leaks
    *ba = tmpBA;
} else {
    // Simulate construction from a null-terminated C-string
    // Note: c_str() is null-terminated; QByteArray(const char*) reads until first null
    std::string tmp = seed.substr(0, initLen);
    const char *cstr = tmp.c_str();
    QByteArray tmpBA(cstr);
    *ba = tmpBA;
}

// Optionally append a small amount of extra fuzz data without exceeding the cap
size_t remaining = (ba->size() < kMaxSize) ? (kMaxSize - ba->size()) : 0;
if (remaining > 0) {
    unsigned int addMode = (*FUZZ_PARAM(unsigned int)) & 1u;
    size_t toAdd = (size_t)((*FUZZ_PARAM(unsigned int)) % 17u); // up to 16 bytes
    if (toAdd > remaining) toAdd = remaining;
    if (toAdd > 0) {
        if (addMode == 0u) {
            // Append buffer slice
            std::string extra = FUZZ_PARAM_STR();
            if (extra.size() > toAdd) extra.resize(toAdd);
            if (!extra.empty()) ba->append(extra.data(), extra.size());
        } else {
            // Append byte-by-byte
            for (size_t i = 0; i < toAdd; ++i) {
                char c = (char)(*FUZZ_PARAM(unsigned int) & 0xFFu);
                ba->append(c);
            }
        }
    }
}

// Track useful metadata for downstream stubs
FUZZ_SET_ATTR_INT(ba, "size", (int)ba->size());

// Property: we strictly enforce the size bound to ensure fast fuzz iterations
FUZZ_ASSERT(ba->size() <= kMaxSize, "QByteArray size should be <= 2048 bytes");

// Validation summary:
// - ba is always allocated and non-null; content built via multiple valid API paths.
// - Size is bounded and attributes are set for downstream consumers; no ownership violations.
